style.css:
@-moz-document domain("youtube.com") {
:root {
  --my-bg: #050505;
  --my-surface: #151515;
  --my-accent: #ff2020;
  --my-text: #f5f5f5;
}

/* black background */
html,
body,
ytd-app {
  background: var(--my-bg) !important;
  color: var(--my-text) !important;
}

/* video cards */
ytd-rich-item-renderer,
ytd-video-renderer {
  background: var(--my-surface) !important;
  border-radius: 14px !important;
}

/* thumbnails */
ytd-thumbnail img {
  border-radius: 14px !important;
}

/* search bar */
#search,
#searchbox,
ytd-searchbox {
  background: var(--my-surface) !important;
  border-radius: 25px !important;
}

/* video titles */
#video-title,
#channel-name {
  color: var(--my-text) !important;
}

/* red accents */
a:hover {
  color: var(--my-accent) !important;
}

/* sidebar */
#guide-content,
ytd-mini-guide-renderer {
  background: var(--my-bg) !important;
}
}
